dbutils.widgets.text("rel_tol", "0.01")
ENDPOINT=dbutils.widgets.get("endpoint"); SUFFIX=dbutils.widgets.get("session_suffix")
TOL=float(dbutils.widgets.get("score_tol")); RTOL=float(dbutils.widgets.get("rel_tol"))

